const req = $input.first().json;
const body = req.body && typeof req.body === 'object' ? req.body : {};
const raw = String(body.url ?? body.link ?? body.video ?? req.query?.url ?? '').trim();
const m = raw.match(/(?:youtube(?:-nocookie)?\.com\/(?:watch\?(?:[^#]*&)?v=|shorts\/|live\/|embed\/|v\/)|youtu\.be\/)([A-Za-z0-9_-]{11})/) || raw.match(/^([A-Za-z0-9_-]{11})$/);
if (!m) return [{ json: { ok: false, status: 400, error: 'Send a YouTube link as url, like {"url": "https://www.youtube.com/watch?v=dQw4w9WgXcQ"}.' } }];
return [{ json: { ok: true, video_id: m[1] } }];

const t = $input.first().json;
const { video_id } = $('Find the video id').first().json;
const refusal = (e) => {
  const msg = String(e.message || '');
  let body = null;
  try { body = JSON.parse(msg.slice(msg.indexOf(' - ') + 3)); if (typeof body === 'string') body = JSON.parse(body); } catch (_) {}
  return { status: Number(e.status || e.httpCode || msg.slice(0, 3)) || 0, code: body?.error?.code || '', text: body?.error?.message || msg };
};
const fail = (status, error) => [{ json: { ok: false, status, error } }];
if (t.error) {
  const e = refusal(t.error);
  // A wrong key is the workflow owner's to fix, so the caller gets a 500 that says where.
  if (e.status === 401 || e.status === 403) return fail(500, `Arcmira didn't accept the API key (${e.code || e.status}). In "Get transcript from Arcmira", pick a Header Auth credential named Authorization with the value "Bearer <your key>".`);
  if (e.status === 402) return fail(402, `Arcmira refused the transcript for credits (${e.code || 402}). ${e.text}`);
  if (e.status === 404) return fail(404, `Arcmira found no transcript for this video (${e.code || 404}). ${e.text}`);
  // 503 transcript_fetching can clear on a later call, so the caller hears it as a 503 too.
  return fail(e.status === 503 ? 503 : 502, `Arcmira couldn't read the transcript (${e.code || e.status || 'error'}). ${e.text}`);
}
const all = (Array.isArray(t.lines) ? t.lines : [])
  .map((l) => ({ start: Number(l.start) || 0, end: Number(l.end ?? l.start) || 0, text: String(l.text || '').replace(/\s+/g, ' ').trim() }));
const lines = all.filter((l) => l.text);
if (!lines.length) return fail(404, 'Arcmira returned an empty transcript for this video.');
const clock = (s) => { s = Math.floor(s); const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
// Transcript lines run 2 to 6 seconds. Blocks of about 30 seconds keep the times useful and the prompt short.
const blocks = [];
for (const l of lines) {
  const last = blocks[blocks.length - 1];
  if (!last || l.start - last.start >= 30) blocks.push({ start: Math.floor(l.start), text: [] });
  blocks[blocks.length - 1].text.push(l.text);
}
const end = Math.ceil(Number(t.video?.duration_seconds) || all.reduce((m, l) => Math.max(m, l.end, l.start), 0));
const title = t.video?.title || '';
const channel = t.video?.channel_name || '';
return [{ json: {
  ok: true, video_id, title, channel, duration_seconds: end, credits: Number(t.rows_billed || 0) * 4,
  watch_url: t.video?.watch_url || `https://www.youtube.com/watch?v=${video_id}`,
  lines: lines.map((l) => ({ start: l.start, text: l.text })),
  prompt: `Video: ${title || video_id}${channel ? ` (${channel})` : ''}\n\nTranscript. Each block starts with its time.\n\n` + blocks.map((b) => `[${clock(b.start)}] ${b.text.join(' ')}`).join('\n'),
} }];

const src = $('Build the timestamped transcript').first().json;
const text = String($input.first().json.text || '').trim();
const link = (s) => `${src.watch_url}${src.watch_url.includes('?') ? '&' : '?'}t=${s}s`;
const TIME = /\[(?:(\d{1,2}):)?(\d{1,2}):(\d{2})\]/;
const seconds = (h, m, s) => (Number(h) || 0) * 3600 + Number(m) * 60 + Number(s);
const clock = (s) => { const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60; return (h ? h + ':' + String(m).padStart(2, '0') : m) + ':' + String(x).padStart(2, '0'); };
// Quotes are compared on letters and digits only, so case, punctuation and curly quotes don't matter.
const norm = (s) => String(s || '').toLowerCase().replace(/['’]/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
let hay = ' ';
const marks = [];
for (const l of src.lines) {
  const n = norm(l.text);
  if (!n) continue;
  marks.push({ at: hay.length - 1, start: l.start });
  hay += n + ' ';
}
const lineStart = (pos) => { let lo = 0, hi = marks.length - 1; while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (marks[mid].at <= pos) lo = mid; else hi = mid - 1; } return marks[lo].start; };
// The line where the quote starts, nearest the time Claude gave. A long quote that differs later still finds its line
// by its first eight words, but only a whole match counts as found in the transcript.
const locate = (quote, near) => {
  const words = norm(quote).split(' ').filter(Boolean);
  const tries = [[words, true]];
  if (words.length > 8) tries.push([words.slice(0, 8), false]);
  for (const [w, whole] of tries) {
    if (!w.length) continue;
    const needle = ' ' + w.join(' ') + ' ';
    let best = null;
    for (let pos = hay.indexOf(needle); pos !== -1; pos = hay.indexOf(needle, pos + 1)) {
      const start = lineStart(pos);
      if (!best || Math.abs(start - near) < Math.abs(best.start - near)) best = { start, whole };
    }
    if (best) return best;
  }
  return null;
};
const moments = [];
let pastEnd = 0, notFound = 0;
const out = text.split('\n').map((line) => {
  const hit = line.match(new RegExp('^(\\s*(?:[-*•]\\s*)?)' + TIME.source + '\\s*[-:–]?\\s*(.+)$'));
  if (!hit) {
    // A time past the end of the video can't be real, so it stays as plain text and is counted.
    return line.replace(new RegExp(TIME.source, 'g'), (all, h, m, s) => {
      const at = seconds(h, m, s);
      if (at > src.duration_seconds) { pastEnd++; return all; }
      return `[${clock(at)}](${link(at)})`;
    });
  }
  const said = hit[5].trim();
  const claimed = seconds(hit[2], hit[3], hit[4]);
  // The quote ends at the line's last quotation mark. Claude sometimes quotes a term earlier in the line too, so each
  // opening mark is tried and the span found in the transcript wins.
  const close = Math.max(said.lastIndexOf('"'), said.lastIndexOf('”'));
  const opens = [...said.matchAll(/(^|\s)["“]/g)].map((o) => o.index + o[1].length).filter((o) => o < close);
  let open = opens.length ? opens[0] : -1, found = null;
  for (const o of opens) {
    const f = locate(said.slice(o + 1, close), claimed);
    if (f && !found) { open = o; found = f; }
    if (f?.whole) { open = o; found = f; break; }
  }
  const quote = open !== -1 ? said.slice(open + 1, close).trim() : '';
  const what = quote ? said.slice(0, open).trim() : said;
  if (quote && !found?.whole) notFound++;
  if (!found && claimed > src.duration_seconds) { pastEnd++; return line; }
  const at = found ? Math.floor(found.start) : claimed;
  moments.push({ at: clock(at), seconds: at, url: link(at), text: what, quote, quote_in_transcript: Boolean(found?.whole) });
  return `${hit[1]}[${clock(at)}](${link(at)}) ${said}`;
});
return [{ json: {
  video: { id: src.video_id, title: src.title, channel: src.channel, url: src.watch_url },
  summary: out.join('\n'), moments,
  quotes_not_in_transcript: notFound, times_past_the_end: pastEnd, arcmira_credits_used: src.credits,
} }];
